/* Sine table, Q12, 0..90 degrees. */
static const int16_t kSinQ12[91] = {
    0, 71, 143, 214, 286, 357, 428, 499, 570, 641, 711, 782, 852, 921, 991, 1060,
    1129, 1198, 1266, 1334, 1401, 1468, 1534, 1600, 1666, 1731, 1796, 1860, 1923, 1986, 2048, 2110,
    2171, 2231, 2290, 2349, 2408, 2465, 2522, 2578, 2633, 2687, 2741, 2793, 2845, 2896, 2946, 2996,
    3044, 3091, 3138, 3183, 3228, 3271, 3314, 3355, 3396, 3435, 3474, 3511, 3547, 3582, 3617, 3650,
    3681, 3712, 3742, 3770, 3798, 3824, 3849, 3873, 3896, 3917, 3937, 3956, 3974, 3991, 4006, 4021,
    4034, 4046, 4056, 4065, 4074, 4080, 4086, 4090, 4094, 4095, 4096
};

int pu20SinQ12(int degrees) {
    int d = degrees % 360;
    if (d < 0) d += 360;
    if (d <= 90)  return  kSinQ12[d];
    if (d <= 180) return  kSinQ12[180 - d];
    if (d <= 270) return -kSinQ12[d - 180];
    return -kSinQ12[360 - d];
}

int pu20CosQ12(int degrees) {
    return pu20SinQ12(degrees + 90);
}

/* ------------------------------------------------------------------------- */
/* Small helpers                                                             */
/* ------------------------------------------------------------------------- */

static uint32_t rgbWord(Pu20Rgb c) {
    return gp0_rgb(c.r, c.g, c.b);
}

void pu20Blend(const Pu20Rgb *a, const Pu20Rgb *b, int t, Pu20Rgb *out) {
    if (t < 0)   t = 0;
    if (t > 255) t = 255;
    out->r = (uint8_t)(((int)a->r * (255 - t) + (int)b->r * t) / 255);
    out->g = (uint8_t)(((int)a->g * (255 - t) + (int)b->g * t) / 255);
    out->b = (uint8_t)(((int)a->b * (255 - t) + (int)b->b * t) / 255);
}

static void fillRect(DMAChain *chain, int x, int y, int w, int h, Pu20Rgb c) {
    if (w <= 0 || h <= 0) return;
    uint32_t *ptr = allocatePacket(chain, 3);
    ptr[0] = rgbWord(c) | gp0_rectangle(false, true, false);
    ptr[1] = gp0_xy(x, y);
    ptr[2] = gp0_xy(w, h);
}

static void fillRectSemi(DMAChain *chain, int x, int y, int w, int h, Pu20Rgb c) {
    if (w <= 0 || h <= 0) return;
    uint32_t *ptr = allocatePacket(chain, 3);
    ptr[0] = rgbWord(c) | gp0_rectangle(false, true, true);
    ptr[1] = gp0_xy(x, y);
    ptr[2] = gp0_xy(w, h);
}

/* Vertical gradient. Implemented as flat bands (unshaded rectangles) so it
 * also works on GPU/renderer combinations that reject gouraud triangles; the
 * band count scales with the height to keep the look smooth and the DMA small. */
static void gradRect(DMAChain *chain, int x0, int y0, int x1, int y1,
                     Pu20Rgb top, Pu20Rgb bottom) {
    int height = y1 - y0;
    int width = x1 - x0;
    int bands = (height + 7) / 8;

    if (width <= 0 || height <= 0) return;
    if (bands < 2)  bands = 2;
    if (bands > 20) bands = 20;

    for (int i = 0; i < bands; i++) {
        int ya = y0 + (height * i) / bands;
        int yb = y0 + (height * (i + 1)) / bands;
        Pu20Rgb color;

        pu20Blend(&top, &bottom, (i * 255) / (bands - 1), &color);
        fillRect(chain, x0, ya, width, yb - ya, color);
    }
}

static void fillCircle(DMAChain *chain, int cx, int cy, int r, Pu20Rgb c,
                       int segments) {
    if (r <= 0 || segments < 3) return;

    int px = cx + ((r * pu20CosQ12(0)) >> 12);
    int py = cy + ((r * pu20SinQ12(0)) >> 12);

    for (int i = 1; i <= segments; i++) {
        int angle = (360 * i) / segments;
        int nx = cx + ((r * pu20CosQ12(angle)) >> 12);
        int ny = cy + ((r * pu20SinQ12(angle)) >> 12);

        uint32_t *ptr = allocatePacket(chain, 4);
        ptr[0] = rgbWord(c) | gp0_triangle(false, false);
        ptr[1] = gp0_xy(cx, cy);
        ptr[2] = gp0_xy(px, py);
        ptr[3] = gp0_xy(nx, ny);

        px = nx;
        py = ny;
    }
}

/* Filled circle with per-segment shading, used by the spinning disc. */
static void shadedCircle(DMAChain *chain, int cx, int cy, int r, Pu20Rgb base,
                         int lightAngle, int segments) {
    if (r <= 0 || segments < 3) return;

    for (int i = 0; i < segments; i++) {
        int a0 = (360 * i) / segments;
        int a1 = (360 * (i + 1)) / segments;
        int mid = a0 + (a1 - a0) / 2;
        int diff = mid - lightAngle;
        diff %= 360;
        if (diff < 0) diff += 360;
        if (diff > 180) diff = 360 - diff;

        int shade = 255 - (diff * 200) / 180; /* 55..255 */
        Pu20Rgb c;
        c.r = (uint8_t)(((int)base.r * shade) / 255);
        c.g = (uint8_t)(((int)base.g * shade) / 255);
        c.b = (uint8_t)(((int)base.b * shade) / 255);

        int px = cx + ((r * pu20CosQ12(a0)) >> 12);
        int py = cy + ((r * pu20SinQ12(a0)) >> 12);
        int nx = cx + ((r * pu20CosQ12(a1)) >> 12);
        int ny = cy + ((r * pu20SinQ12(a1)) >> 12);

        uint32_t *ptr = allocatePacket(chain, 4);
        ptr[0] = rgbWord(c) | gp0_triangle(false, false);
        ptr[1] = gp0_xy(cx, cy);
        ptr[2] = gp0_xy(px, py);
        ptr[3] = gp0_xy(nx, ny);
    }
}

static void appendNumber2(char *buffer, int value) {
    if (value < 0)    value = 0;
    if (value > 99)   value = 99;
    buffer[0] = (char)('0' + (value / 10));
    buffer[1] = (char)('0' + (value % 10));
    buffer[2] = '\0';
}

void pu20FormatTime(char *buffer, size_t size, uint32_t frames) {
    if (size < 6) {
        if (size > 0) buffer[0] = '\0';
        return;
    }

    uint32_t seconds = frames / 75u;
    uint32_t minutes = seconds / 60u;
    uint32_t secs    = seconds % 60u;

    if (minutes > 99u) minutes = 99u;

    buffer[0] = (char)('0' + (minutes / 10u));
    buffer[1] = (char)('0' + (minutes % 10u));
    buffer[2] = ':';
    buffer[3] = (char)('0' + (secs / 10u));
    buffer[4] = (char)('0' + (secs % 10u));
    buffer[5] = '\0';
}

/* ------------------------------------------------------------------------- */
/* Lifecycle                                                                 */
/* ------------------------------------------------------------------------- */

void pu20SkinInit(void) {
    memset(&s_atlasTex, 0, sizeof(s_atlasTex));
    s_assetsReady = false;
}

void pu20SkinUploadAssets(void) {
    pu20UploadTexture(
        &s_atlasTex,
        s_iconAtlas,
        pu20IconPalette,
        PU20_ATLAS_X,
        PU20_ATLAS_Y,
        PU20_ATLAS_CLUT_X,
        PU20_ATLAS_CLUT_Y,
        PU20_ATLAS_WIDTH,
        PU20_ATLAS_HEIGHT,
        GP0_COLOR_4BPP
    );
    pu20SkinUploadShellAssets();
    s_assetsReady = true;
}

/* ------------------------------------------------------------------------- */
/* Icons                                                                     */
/* ------------------------------------------------------------------------- */

static void drawIconInternal(DMAChain *chain, Pu20Icon icon, int x, int y,
                             const Pu20Rgb *tint) {
    if (!s_assetsReady || icon < 0 || icon >= PU20_ICON_COUNT) return;

    int u = (icon % PU20_ICON_COLUMNS) * PU20_ICON_SIZE;
    int v = (icon / PU20_ICON_COLUMNS) * PU20_ICON_SIZE;

    uint32_t *ptr = allocatePacket(chain, 5);
    ptr[0] = gp0_texpage(s_atlasTex.page, false, true);
    if (tint) {
        ptr[1] = rgbWord(*tint) | gp0_rectangle(true, false, false);
        ptr[2] = gp0_xy(x, y);
        ptr[3] = gp0_uv((unsigned int)(s_atlasTex.u + u),
                        (unsigned int)(s_atlasTex.v + v), s_atlasTex.clut);
        ptr[4] = gp0_xy(PU20_ICON_SIZE, PU20_ICON_SIZE);
    } else {
        ptr[1] = gp0_rectangle(true, true, false);
        ptr[2] = gp0_xy(x, y);
        ptr[3] = gp0_uv((unsigned int)(s_atlasTex.u + u),
                        (unsigned int)(s_atlasTex.v + v), s_atlasTex.clut);
        ptr[4] = gp0_xy(PU20_ICON_SIZE, PU20_ICON_SIZE);
    }
}

void pu20DrawIcon(DMAChain *chain, Pu20Icon icon, int x, int y) {
    drawIconInternal(chain, icon, x, y, NULL);
}

void pu20DrawIconTinted(DMAChain *chain, Pu20Icon icon, int x, int y, Pu20Rgb tint) {
    drawIconInternal(chain, icon, x, y, &tint);
}

