/* --- Generated BIOS-style pt-BR font (with oy baseline + drop shadow) ----- */

typedef struct {
    const TextureInfo *tex;
    const Pu20Glyph *glyphs;
    const uint8_t *index;
} Pu20FontRef;

static const Pu20FontRef kFonts[2] = {
    { &s_fontSmall,  s_smallGlyph,  s_smallIndex  },
    { &s_fontMedium, s_mediumGlyph, s_mediumIndex }
};

/* Decode UTF-8 Latin-1 (e.g. Á À Â Ã É Ê Í Ó Ô Õ Ú Ü Ç), common Unicode
 * punctuation (curly quotes, dashes, ellipsis), or raw Latin-1 bytes. */
static uint8_t pu20NextLatin1(const char **text) {
    uint8_t c = (uint8_t) **text;

    (*text)++;
    if (c == 0xC2u && (uint8_t) **text >= 0x80u &&
        (uint8_t) **text <= 0xBFu) {
        uint8_t b1 = (uint8_t) *((*text)++);
        return (b1 == 0xA0u) ? (uint8_t) ' ' : b1;
    }
    if (c == 0xC3u && (uint8_t) **text >= 0x80u &&
        (uint8_t) **text <= 0xBFu) {
        return (uint8_t) (0x40u + (uint8_t) *((*text)++));
    }
    /* UTF-8 General Punctuation U+2000..U+203F (0xE2 0x80 0x80..0xBF) */
    if (c == 0xE2u && (uint8_t) (*text)[0] == 0x80u &&
        (uint8_t) (*text)[1] >= 0x80u && (uint8_t) (*text)[1] <= 0xBFu) {
        uint8_t b2 = (uint8_t) (*text)[1];
        (*text) += 2;
        if (b2 >= 0x98u && b2 <= 0x9Bu) return (uint8_t) '\'';
        if (b2 >= 0x9Cu && b2 <= 0x9Fu) return (uint8_t) '"';
        if (b2 >= 0x90u && b2 <= 0x95u) return (uint8_t) '-';
        if (b2 == 0xA6u)                return (uint8_t) '.';
        return (uint8_t) ' ';
    }
    return c;
}

static void pu20FontPass(DMAChain *chain, const Pu20FontRef *f, int x, int y,
                         int maxX, const char *text, Pu20Rgb color) {
    uint32_t *page = allocatePacket(chain, 1);
    uint32_t mod   = ppModRgb(color);

    page[0] = gp0_texpage(f->tex->page, false, true);

    for (; *text;) {
        uint8_t gi = f->index[pu20NextLatin1(&text)];
        const Pu20Glyph *g;
        uint32_t *p;

        if (gi == 0xFF) {
            if (maxX > 0 && x + 5 > maxX) break;
            x += 5;
            continue;
        }
        g = &f->glyphs[gi];
        if (g->w == 0) {
            if (maxX > 0 && x + g->adv > maxX) break;
            x += g->adv;
            continue;
        }
        if (maxX > 0 && x + g->w > maxX) break;

        /* unshaded = false enables GPU colour modulation (black drop shadow +
         * crisp white/tinted foreground). Apply g->oy for exact baseline!
         * +1px tracking keeps glyphs crisp and airy like PicoMenu's font. */
        p = allocatePacket(chain, 4);
        p[0] = gp0_rectangle(true, false, false) | mod;
        p[1] = gp0_xy(x, y + (int) g->oy);
        p[2] = gp0_uv(f->tex->u + g->u, f->tex->v + g->v, f->tex->clut);
        p[3] = gp0_xy(g->w, g->h);
        x += (int) g->adv + 1;
    }
}

int pu20FontWidth(int size, const char *text) {
    const Pu20FontRef *f;
    int w = 0;

    if (size < 0 || size > 1 || !text) return 0;
    f = &kFonts[size];

    for (; *text;) {
        uint8_t gi = f->index[pu20NextLatin1(&text)];
        if (gi == 0xFF) { w += 5; continue; }
        if (f->glyphs[gi].w == 0) { w += f->glyphs[gi].adv; continue; }
        w += (int) f->glyphs[gi].adv + 1;
    }
    return w;
}

void pu20DrawFont(DMAChain *chain, int size, int x, int y, const char *text,
                  Pu20Rgb color) {
    if (size < 0 || size > 1 || !text || !s_shellReady) return;
    pu20FontPass(chain, &kFonts[size], x + 1, y + 1, 0, text, kBlack);
    pu20FontPass(chain, &kFonts[size], x, y, 0, text, color);
}

void pu20DrawFontClipped(DMAChain *chain, int size, int x, int y, int maxX,
                         const char *text, Pu20Rgb color) {
    if (size < 0 || size > 1 || !text || !s_shellReady) return;
    pu20FontPass(chain, &kFonts[size], x + 1, y + 1, maxX + 1, text, kBlack);
    pu20FontPass(chain, &kFonts[size], x, y, maxX, text, color);
}

void pu20DrawFontClean(DMAChain *chain, int size, int x, int y, const char *text,
                       Pu20Rgb color) {
    if (size < 0 || size > 1 || !text || !s_shellReady) return;
    pu20FontPass(chain, &kFonts[size], x, y, 0, text, color);
}

void pu20DrawFontClippedClean(DMAChain *chain, int size, int x, int y, int maxX,
                              const char *text, Pu20Rgb color) {
    if (size < 0 || size > 1 || !text || !s_shellReady) return;
    pu20FontPass(chain, &kFonts[size], x, y, maxX, text, color);
}

