void pu20DrawShellCursor(DMAChain *chain, int x, int y) {
    /* 1:1 PU-20 3D pink pointer cone pointing UP-LEFT from sharp tip (x, y). */
    Pu20Rgb tipCol    = { 0xFF, 0xD8, 0xFA };
    Pu20Rgb ridgeCol  = { 0xFF, 0xE8, 0xFF };
    Pu20Rgb topEdge   = { 0xFF, 0x58, 0xDC };
    Pu20Rgb foldDark  = { 0x98, 0x10, 0x80 };
    Pu20Rgb botEdge   = { 0xEE, 0x38, 0xC8 };

    /* Top lit facet: (0,0) -> (+32,+10) -> (+26,+15) */
    gTri(chain, x, y, tipCol,
         x + 32, y + 10, topEdge,
         x + 26, y + 15, ridgeCol, false);
    /* Shaded central crease: (0,0) -> (+26,+15) -> (+20,+20) */
    gTri(chain, x, y, ridgeCol,
         x + 26, y + 15, topEdge,
         x + 20, y + 20, foldDark, false);
    /* Lower magenta rim facet: (0,0) -> (+20,+20) -> (+14,+24) */
    gTri(chain, x, y, tipCol,
         x + 20, y + 20, foldDark,
         x + 14, y + 24, botEdge, false);
}

