/* --- Panels, buttons, splats, arrow -------------------------------------- */

void pu20DrawTitlePanelRect(DMAChain *chain, int x, int y, int w, int h) {
    /* Exact PU-20 title box: dark navy edges (#000010), luminous vertical blue
     * glow down the center (#2A3AB8), and a crisp 2px bright blue border on
     * all 4 sides (#3141C5). */
    Pu20Rgb edge   = { 0x00, 0x00, 0x10 };
    Pu20Rgb glow   = { 0x2A, 0x3A, 0xB8 };
    Pu20Rgb border = { 0x31, 0x41, 0xC5 };
    int midX = x + w / 2;

    gQuad(chain, x + 2, y + 2, midX, y + h - 2, edge, glow, edge, glow, false);
    gQuad(chain, midX, y + 2, x + w - 2, y + h - 2, glow, edge, glow, edge,
          false);

    fillRect(chain, x, y, w, 2, border);
    fillRect(chain, x, y + h - 2, w, 2, border);
    fillRect(chain, x, y, 2, h, border);
    fillRect(chain, x + w - 2, y, 2, h, border);
}

void pu20DrawTitlePanel(DMAChain *chain, const TextureInfo *font,
                        const char *title) {
    int x = 184, y = 20, w = 128, h = 23;
    int textWidth;
    int textX;

    (void) font;
    pu20DrawTitlePanelRect(chain, x, y, w, h);

    textWidth = pu20FontWidth(0, title);
    textX     = x + (w - textWidth) / 2;
    if (textX < x + 4) textX = x + 4;

    pu20DrawFont(chain, 0, textX, y + 6, title, kWhite);
}

void pu20DrawShellButton(DMAChain *chain, int x, int y, int w, int h,
                         bool focused) {
    /* Authentic PU-20 flat lavender-blue tile (#41418B) seamlessly integrated
     * over the concentric rings (no heavy dark borders or bottom drop bar). */
    Pu20Rgb fill = focused ? (Pu20Rgb){ 0x56, 0x56, 0xB4 }
                           : (Pu20Rgb){ 0x41, 0x41, 0x8B };

    fillRect(chain, x, y, w, h, fill);
}

void pu20DrawMenuButton(DMAChain *chain, const TextureInfo *font,
                        int x, int y, int w, int h, const char *label,
                        bool selected) {
    Pu20Rgb fill = selected ? (Pu20Rgb){ 0x58, 0x58, 0xB8 }
                            : (Pu20Rgb){ 0x41, 0x41, 0x8B };
    int textWidth;
    int textX;

    fillRect(chain, x, y, w, h, fill);

    if (label && font) {
        textWidth = rc5MeasureString(label);
        textX     = x + (w - textWidth) / 2;
        if (textX < x + 1) textX = x + 1;
        pu20DrawTextShadow(chain, font, textX, y + (h - 13) / 2, label,
                           x + w - 1, kWhite);
    }
}

void pu20DrawGlossPanel(DMAChain *chain, int x, int y, int w, int h,
                        bool selected) {
    Pu20Rgb top    = selected ? (Pu20Rgb){ 0x5A, 0x5A, 0xB0 }
                              : (Pu20Rgb){ 0x40, 0x40, 0x92 };
    Pu20Rgb bottom = selected ? (Pu20Rgb){ 0x28, 0x28, 0x70 }
                              : (Pu20Rgb){ 0x16, 0x16, 0x42 };

    ppChainBlend(chain, GP0_BLEND_SEMITRANS);
    gQuad(chain, x, y, x + w, y + h, top, top, bottom, bottom, true);

    fillRect(chain, x, y, w, 1, (Pu20Rgb){ 0x6A, 0x6A, 0xC8 });
    fillRect(chain, x, y, 1, h, (Pu20Rgb){ 0x6A, 0x6A, 0xC8 });
    fillRect(chain, x, y + h - 1, w, 1, (Pu20Rgb){ 0x30, 0x30, 0x60 });
    fillRect(chain, x + w - 1, y, 1, h, (Pu20Rgb){ 0x30, 0x30, 0x60 });
}

void pu20DrawSplat(DMAChain *chain, int cx, int cy, int w, int h,
                   uint32_t seed) {
    int x0, y0, x1, y1;
    unsigned int u0, u1, v0, v1;
    uint32_t *p;

    if (!s_shellReady || w <= 0 || h <= 0) return;

    x0 = cx - w / 2;
    y0 = cy - h / 2;
    x1 = x0 + w;
    y1 = y0 + h;

    u0 = s_splatTexInfo.u;
    u1 = s_splatTexInfo.u + PU20_SPLAT_W - 1u;
    v0 = s_splatTexInfo.v;
    v1 = s_splatTexInfo.v + PU20_SPLAT_H - 1u;
    if (seed & 1u) { unsigned int t = u0; u0 = u1; u1 = t; }
    if (seed & 2u) { unsigned int t = v0; v0 = v1; v1 = t; }

    p = allocatePacket(chain, 9);
    p[0] = gp0_quad(true, false);
    p[1] = gp0_xy(x0, y0);
    p[2] = gp0_uv(u0, v0, s_splatTexInfo.clut);
    p[3] = gp0_xy(x1, y0);
    p[4] = gp0_uv(u1, v0, s_splatTexInfo.page);
    p[5] = gp0_xy(x0, y1);
    p[6] = gp0_uv(u0, v1, 0);
    p[7] = gp0_xy(x1, y1);
    p[8] = gp0_uv(u1, v1, 0);
}

void pu20DrawArrow(DMAChain *chain, int x, int y, uint32_t frame) {
    int bob = (int) ((frame >> 4) & 1u);
    Pu20Rgb tipCol   = { 0xFF, 0xD8, 0xFA };
    Pu20Rgb ridgeCol = { 0xFF, 0xE8, 0xFF };
    Pu20Rgb topEdge  = { 0xFF, 0x58, 0xDC };
    Pu20Rgb foldDark = { 0x98, 0x10, 0x80 };
    Pu20Rgb botEdge  = { 0xEE, 0x38, 0xC8 };

    y += bob;
    /* Half-scale 3D pink pointer for 320x240 demo screens. */
    gTri(chain, x, y, tipCol,
         x + 16, y + 5, topEdge,
         x + 13, y + 8, ridgeCol, false);
    gTri(chain, x, y, ridgeCol,
         x + 13, y + 8, topEdge,
         x + 10, y + 10, foldDark, false);
    gTri(chain, x, y, tipCol,
         x + 10, y + 10, foldDark,
         x + 7, y + 12, botEdge, false);
}

static void fillRing(DMAChain *chain, int cx, int cy, int rIn, int rOut,
                     Pu20Rgb c, int segments) {
    int ix0 = cx + rIn;
    int iy0 = cy;
    int ox0 = cx + rOut;
    int oy0 = cy;

    if (rOut <= rIn || segments < 3) return;

    for (int i = 1; i <= segments; i++) {
        int a   = (360 * i) / segments;
        int cs  = pu20CosQ12(a);
        int sn  = pu20SinQ12(a);
        int ix1 = cx + ((rIn  * cs) >> 12);
        int iy1 = cy + ((rIn  * sn) >> 12);
        int ox1 = cx + ((rOut * cs) >> 12);
        int oy1 = cy + ((rOut * sn) >> 12);
        uint32_t *ptr = allocatePacket(chain, 5);

        ptr[0] = rgbWord(c) | gp0_quad(false, false);
        ptr[1] = gp0_xy(ix0, iy0);
        ptr[2] = gp0_xy(ox0, oy0);
        ptr[3] = gp0_xy(ix1, iy1);
        ptr[4] = gp0_xy(ox1, oy1);

        ix0 = ix1;
        iy0 = iy1;
        ox0 = ox1;
        oy0 = oy1;
    }
}

void pu20DrawShellBackground(DMAChain *chain, int w, int h, uint32_t frame) {
    /* Fast clean-room PU-20 concentric radial rings:
     *   - single solid rectangle for dark-blue outer margin (1 GP0 primitive)
     *   - 12 crisp non-overlapping annular rings x 20 segments (480 tris total,
     *     < 4 ms on real PS1 GPU so 640x480i finishes inside a single field!). */
    Pu20Rgb outer = { 0, 0, 32 };
    int cx = w / 2;
    int cy = h / 2;
    int maxR = (w >= 640) ? 290 : 145;
    int rings = (w >= 640) ? 10 : 12;
    int segs  = (w >= 640) ? 16 : 20;
    uint32_t *tp = allocatePacket(chain, 1);

    (void) frame;
    tp[0] = gp0_texpage(0, false, true);

    fillRect(chain, 0, 0, w, h, outer);

    for (int k = rings - 1; k >= 1; k--) {
        int rIn  = (maxR * k) / rings - 1;
        int rOut = (maxR * (k + 1)) / rings + 1;
        int inv  = rings - 1 - k;
        int rg   = ((128 * inv) / (rings - 1)) & ~7;
        int b    = (32 + (223 * inv) / (rings - 1)) & ~7;
        Pu20Rgb col;

        if (rIn < 1) rIn = 1;
        if (b > 255) b = 255;
        col.r = (uint8_t) rg;
        col.g = (uint8_t) rg;
        col.b = (uint8_t) b;
        fillRing(chain, cx, cy, rIn, rOut, col, segs);
    }

    {
        int r0 = maxR / rings + 1;
        fillCircle(chain, cx, cy, r0, (Pu20Rgb){ 131, 131, 255 }, segs);
    }
}

void pu20DrawMainBackground(DMAChain *chain, uint32_t frame) {
    pu20DrawShellBackground(chain, 320, 240, frame);

    /* Exact PU-20 BIOS main-menu sphere clusters (top-left pair & bottom pair) */
    pu20DrawSphereClut(chain, 74, 34, 28, PU20_CLUT_INDIGO);
    pu20DrawSphereClut(chain, 106, 56, 20, PU20_CLUT_INDIGO);
    pu20DrawSphereClut(chain, 118, 178, 15, PU20_CLUT_INDIGO);
    pu20DrawSphereClut(chain, 150, 194, 30, PU20_CLUT_INDIGO);
}

void pu20DrawVortexBackground(DMAChain *chain, uint32_t frame) {
    pu20DrawShellBackground(chain, 320, 240, frame);
}

/* --- Tiny 3x5 labels ----------------------------------------------------- */

static const uint8_t kTinyFont[7][5] = {
    { 0b101, 0b111, 0b111, 0b101, 0b101 }, /* M */
    { 0b111, 0b010, 0b010, 0b010, 0b111 }, /* I */
    { 0b101, 0b111, 0b111, 0b111, 0b101 }, /* N */
    { 0b011, 0b100, 0b010, 0b001, 0b110 }, /* S */
    { 0b111, 0b100, 0b110, 0b100, 0b111 }, /* E */
    { 0b011, 0b100, 0b100, 0b100, 0b011 }, /* C */
    { 0b011, 0b100, 0b101, 0b101, 0b011 }  /* G */
};

void pu20DrawTinyText(DMAChain *chain, int x, int y, const char *text) {
    for (; *text; text++, x += 4) {
        int index = -1;

        switch (*text) {
            case 'M': index = 0; break;
            case 'I': index = 1; break;
            case 'N': index = 2; break;
            case 'S': index = 3; break;
            case 'E': index = 4; break;
            case 'C': index = 5; break;
            case 'G': index = 6; break;
            default: break;
        }
        if (index < 0) continue;

        for (int row = 0; row < 5; row++) {
            uint8_t bits = kTinyFont[index][row];
            for (int col = 0; col < 3; col++) {
                if (bits & (0b100 >> col)) {
                    fillRect(chain, x + col, y + row, 1, 1, kWhite);
                }
            }
        }
    }
}

