void pu20SetBlendMode(int mode) {
    waitForDMADone();
    waitForGP0Ready();
    GPU_GP0 = gp0_texpage(
        gp0_page(0, 0, (GP0BlendMode) mode, GP0_COLOR_16BPP), false, true
    );
}

void pu20DrawSemiRect(DMAChain *chain, int x, int y, int w, int h,
                      Pu20Rgb color) {
    uint32_t *p;

    ppChainBlend(chain, GP0_BLEND_SEMITRANS);
    p = allocatePacket(chain, 3);
    p[0] = rgbWord(color) | gp0_rectangle(false, true, true);
    p[1] = gp0_xy(x, y);
    p[2] = gp0_xy(w, h);
}

void pu20DrawSubtractRect(DMAChain *chain, int x, int y, int w, int h,
                          Pu20Rgb sub) {
    uint32_t *p;

    /* PS1 hardware Back - Front subtraction: pure black (0,0,0) stays 0,
     * while bright trails decay smoothly all the way to pure black! */
    ppChainBlend(chain, GP0_BLEND_SUBTRACT);
    p = allocatePacket(chain, 3);
    p[0] = rgbWord(sub) | gp0_rectangle(false, true, true);
    p[1] = gp0_xy(x, y);
    p[2] = gp0_xy(w, h);
}

void pu20SetChainBlend(DMAChain *chain, int mode) {
    ppChainBlend(chain, mode);
}

void pu20DrawRing(DMAChain *chain, int cx, int cy, int rIn, int rOut,
                  Pu20Rgb color, int segments) {
    fillRing(chain, cx, cy, rIn, rOut, color, segments);
}

void pu20DrawEllipseRing(DMAChain *chain, int cx, int cy,
                         int rxIn, int rxOut, int ryIn, int ryOut,
                         Pu20Rgb color, int segments) {
    int ix0 = cx + rxIn;
    int iy0 = cy;
    int ox0 = cx + rxOut;
    int oy0 = cy;

    if (rxOut <= rxIn || ryOut <= ryIn || segments < 3) return;

    for (int i = 1; i <= segments; i++) {
        int a   = (360 * i) / segments;
        int cs  = pu20CosQ12(a);
        int sn  = pu20SinQ12(a);
        int ix1 = cx + ((rxIn  * cs) >> 12);
        int iy1 = cy + ((ryIn  * sn) >> 12);
        int ox1 = cx + ((rxOut * cs) >> 12);
        int oy1 = cy + ((ryOut * sn) >> 12);
        uint32_t *ptr = allocatePacket(chain, 5);

        ptr[0] = rgbWord(color) | gp0_quad(false, false);
        ptr[1] = gp0_xy(ix0, iy0);
        ptr[2] = gp0_xy(ox0, oy0);
        ptr[3] = gp0_xy(ix1, iy1);
        ptr[4] = gp0_xy(ox1, oy1);

        ix0 = ix1;
        iy0 = iy1;
        ox0 = ox1;
        oy0 = oy1;
    }
}

void pu20DrawShadedDisc(DMAChain *chain, int cx, int cy, int r, Pu20Rgb base,
                        int lightAngle, int segments) {
    shadedCircle(chain, cx, cy, r, base, lightAngle, segments);
}

void pu20DrawShadedEllipse(DMAChain *chain, int cx, int cy, int rx, int ry,
                           Pu20Rgb base, int lightAngle, int segments) {
    if (rx <= 0 || ry <= 0 || segments < 3) return;

    for (int i = 0; i < segments; i++) {
        int a0 = (360 * i) / segments;
        int a1 = (360 * (i + 1)) / segments;
        int mid = a0 + (a1 - a0) / 2;
        int diff = mid - lightAngle;
        diff %= 360;
        if (diff < 0) diff += 360;
        if (diff > 180) diff = 360 - diff;

        int shade = 255 - (diff * 200) / 180;
        Pu20Rgb c;
        c.r = (uint8_t)(((int)base.r * shade) / 255);
        c.g = (uint8_t)(((int)base.g * shade) / 255);
        c.b = (uint8_t)(((int)base.b * shade) / 255);

        int px = cx + ((rx * pu20CosQ12(a0)) >> 12);
        int py = cy + ((ry * pu20SinQ12(a0)) >> 12);
        int nx = cx + ((rx * pu20CosQ12(a1)) >> 12);
        int ny = cy + ((ry * pu20SinQ12(a1)) >> 12);

        uint32_t *ptr = allocatePacket(chain, 4);
        ptr[0] = rgbWord(c) | gp0_triangle(false, false);
        ptr[1] = gp0_xy(cx, cy);
        ptr[2] = gp0_xy(px, py);
        ptr[3] = gp0_xy(nx, ny);
    }
}

void pu20DrawFlatEllipse(DMAChain *chain, int cx, int cy, int rx, int ry,
                         Pu20Rgb c) {
    int px = cx + rx;
    int py = cy;

    if (rx <= 0 || ry <= 0) return;

    for (int i = 1; i <= 32; i++) {
        int a = (360 * i) / 32;
        int nx = cx + ((rx * pu20CosQ12(a)) >> 12);
        int ny = cy + ((ry * pu20SinQ12(a)) >> 12);
        uint32_t *ptr = allocatePacket(chain, 4);

        ptr[0] = rgbWord(c) | gp0_triangle(false, false);
        ptr[1] = gp0_xy(cx, cy);
        ptr[2] = gp0_xy(px, py);
        ptr[3] = gp0_xy(nx, ny);
        px = nx;
        py = ny;
    }
}
